1	// Which packs does this repo's shape suspect, that its declaration does not carry?
2	//
3	// A pack's `detect` fingerprint is consulted exactly once today — at bootstrap's
4	// `--init`, when the declaration is first written. Nothing re-asks afterwards, so a
5	// repo that grows into a pack months later (adds a package.json, a firebase.json, a
6	// JWT library) is never told the pack exists. This module is the re-ask, and it is
7	// deliberately the SELF-CONTAINED PER-REPO HALF: it answers the question for ONE
8	// context and knows nothing about any fleet, any owner, or any other repo.
9	//
10	// It is a SUSPICION, not a verdict. `pack-declaration` was deliberately retired as a
11	// conformance check (engine/checks/README.md) because whether to declare a pack is
12	// the project's call — a marker is a way to suspect a pack is wanted, never proof it
13	// must be. So nothing here returns a finding, blocks, or writes: it returns a list a
14	// caller may act on, and every caller so far turns it into something a human reviews.
15	//
16	// Still pack-agnostic by construction: it names no pack and reads no pack's
17	// internals beyond the manifest fields every pack has. `evaluate` is injected rather
18	// than calling `pack.detect(ctx)` here, because a caller that cannot serve file
19	// CONTENTS synchronously (a remote tree listing, say) must be able to answer "I could
20	// not decide this one" without that being mistaken for "no".
21	
22	import { packEntryId } from '../../../../engine/pack_loader/pack-registry.mjs';
23	
24	// The packs a fit sweep may consider at all: canon packs (a local pack is declared by
25	// hand, never fingerprinted — pack-registry) that carry a fingerprint and are not
26	// already declared. A pack with `detect: null` is declaration-authoritative in BOTH
27	// directions and is not a candidate — its absence from a declaration says nothing.
28	export function fitCandidates(packs, declaredEntries = []) {
29	  const declared = new Set((declaredEntries ?? []).map(packEntryId).filter((id) => id !== undefined));
30	  return packs.filter((p) => typeof p.detect === 'function' && !p.local && !declared.has(p.id));
31	}
32	
33	// Run each candidate's fingerprint and split the answers three ways.
34	//
35	//   evaluate(pack) → true    the repo's shape matches — an undeclared FIT
36	//                  → false   it does not — silence, which is the common case
37	//                  → null    UNDECIDED: this caller could not serve what the
38	//                            fingerprint asked for (see the remote-context note in
39	//                            the claudinite-fleet-sheepdog fit sweep). Reported, never dropped.
40	//
41	// It may return `{ verdict, why }` instead, to say WHY it could not decide, and it
42	// may be async — a caller reading another repo over the network is the reason this
43	// function is awaited at all.
44	//
45	// A fingerprint that THROWS is undecided too, with the error text as the reason — a
46	// broken predicate must not be able to make a fleet look clean.
47	//
48	// Returns { fits: [id], undecided: [{ id, why }] }, both sorted, so a caller can
49	// render a full roster: every candidate lands under exactly one of the three states
50	// (fit, undecided, or the quiet majority that simply did not match).
51	export async function undeclaredFits({ packs, declared = [], evaluate }) {
52	  const fits = [];
53	  const undecided = [];
54	  for (const pack of fitCandidates(packs, declared)) {
55	    let answer;
56	    try {
57	      answer = await evaluate(pack);
58	    } catch (e) {
59	      undecided.push({ id: pack.id, why: `fingerprint threw: ${e.message}` });
60	      continue;
61	    }
62	    const verdict = answer && typeof answer === 'object' ? answer.verdict : answer;
63	    if (verdict === true) fits.push(pack.id);
64	    else if (verdict !== false) {
65	      const why = (answer && typeof answer === 'object' && answer.why)
66	        || 'the fingerprint could not be evaluated here';
67	      undecided.push({ id: pack.id, why });
68	    }
69	  }
70	  return {
71	    fits: fits.sort(),
72	    undecided: undecided.sort((a, b) => a.id.localeCompare(b.id)),
73	  };
74	}
75	
76	// The local answer: a real checkout, a real context, so every fingerprint is
77	// decidable and `undecided` comes back empty unless a predicate threw. This is what
78	// a session in the repo itself should use — it is the complete answer the remote,
79	// path-only view can only approximate.
80	export function localFits({ ctx, packs, declared = [] }) {
81	  return undeclaredFits({ packs, declared, evaluate: (pack) => pack.detect(ctx) === true });
82	}
83

