// The headless-browser pack: driving a real browser from your own process —
// resolving and pinning the build, replacing everything about the page's world
// that would otherwise vary, and the capture mechanics. Prose only, and
// deliberately so: every rule here is a RUNTIME browser behaviour (a secure
// origin gating geolocation, font fallback deciding layout, a scroll dismissing
// a hover state) or an authoring judgment about a harness's shape. Neither has a
// repo-state signature a check could read without asserting that some particular
// call still exists, which pins a point in time rather than a rule.
//
// Fingerprinted by an actual driver reference in JS/TS source — the module
// specifier of a browser-automation package, or a `.launch(` call site — so a
// repo that drives a browser from a globally-installed driver (no dependency
// entry anywhere) is still recognised. The marker only *suspects* the pack;
// declaring it is the project's call, like every pack.

const DRIVER_MODULE = /['"](playwright(?:-core)?|puppeteer(?:-core)?)['"]/;
const LAUNCH_CALL = /\b(?:chromium|firefox|webkit|puppeteer)\.launch\s*\(/;
const SOURCE = /\.(mjs|cjs|js|jsx|ts|tsx)$/;

export default {
  version: '60902.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs:
      'driving a real browser from code — resolving and pinning the build, faking the page world, capture mechanics',
    excludes:
      'which engine a UI golden needs and its review gate — basics writing-tests; workflow wiring — git-github',
  },
  marker: 'a browser-automation driver (playwright / puppeteer, or a .launch( call) referenced in JS/TS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && (DRIVER_MODULE.test(text) || LAUNCH_CALL.test(text));
    }),
};
===JWT===
// The JSON Web Token pack: minting and validating JWTs safely, distilled from
// The JWT Handbook (Sebastián E. Peyrott, Auth0). Prose-free — the teaching
// rides two action skills (jwt-minting, jwt-validation) whose check-the-world
// rules carry the rules in their failure messages: the alg:none bypass, the
// unpinned-algorithm confusion attacks, substitution via unbound audience,
// hardcoded/weak HMAC secrets, and never-expiring tokens. What a static sweep
// cannot judge (key-type/API discipline, nested-JWT validation order, JWE vs
// JWS guarantees) lives in the skills, read at usage time only.
//
// Fingerprinted by a JWT library reference in JS/TS/Python source. The marker
// only *suspects* the pack; declaring it is the project's call, like every pack.
// JWT practice moves with the outside world — an advisory or a revised best
// current practice can date this pack's guidance while nothing here is edited —
// so the README declares the sources that carry it, and the canon's own
// upstream-watch reconciles the content against them.
const JWT_LIB = /['"](jsonwebtoken|express-jwt|jwks-rsa|node-jose|jose|python-jose)['"]|^\s*(import\s+jwt\b|from\s+jwt(\.[\w.]*)?\s+import\b)/m;
const SOURCE = /\.(mjs|cjs|js|jsx|ts|tsx|py)$/;

export default {
  version: '60901.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'minting and validating JSON Web Tokens: algorithm pinning, claim validation, key strength and secrecy, expiry, JWE',
    excludes: 'the Google-issuer validator config — google-identity; OAuth client-side token acquisition — chrome-extension',
  },
  marker: 'a JWT library (jsonwebtoken / jose / PyJWT) referenced in JS/TS/Python source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && JWT_LIB.test(text);
    }),
};
===LEAFLET===

// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
// Leaflet.markercluster). Most are runtime behaviours with no repo-state
// signature and stay prose; the CDN wiring of the assets themselves is written
// into the HTML, and a tile layer's attribution is written into its own options
// object, so those convert. Fingerprinted by an actual Leaflet reference: a
// CDN asset (leaflet@ / leaflet.js / leaflet.css) in HTML, or a Leaflet API call
// site (L.map( / L.tileLayer( / L.markerClusterGroup() ) in source. The marker
// only *suspects* the pack; declaring it is the project's call, like every pack.

const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;

export default {
  version: '60902.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'map rendering with the Leaflet library — map init options, tile layers, markers and divIcons, CDN plugin pinning',
    excludes: 'generic HTML markup rules — that is html; non-map dependency policy belongs to node',
  },
  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
    }),
};
===WEBSPEECH===
// The browser voice-I/O pack: speech-to-text (webkitSpeechRecognition / the Web
// Speech SpeechRecognition API) and text-to-speech (chrome.tts / speechSynthesis)
// runtime gotchas that apply whenever an app reads or listens through the browser.
// Most rules stay prose — runtime browser behaviours, not repo-state signatures a
// static check could test — but two groups do have a static signature: the six
// call-site contracts in worldRules/ (mic release, mic constraints not confused
// with screen-capture ones, a total error-name mapping, an interim-results gate,
// the STT terminal-handler pair, and TTS promise settlement), and the
// web-speech-io skill's three rules (a Window-scoped speech API in the MV3
// service worker, a bare webkit-prefixed recognizer construction, and a mic
// capture the whole repo releases nowhere on pagehide). Fingerprinted by an
// actual speech-API reference in JS/TS source (the marker only *suspects* the
// pack; declaring it is the project's call, like every pack).
const SPEECH_API =
  /\b(webkitSpeechRecognition|SpeechRecognition|SpeechRecognitionPhrase|speechSynthesis|SpeechSynthesisUtterance|chrome\.tts)\b/;
const SOURCE = /\.(mjs|cjs|js|jsx|ts|tsx)$/;

export default {
  version: '60906.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'browser voice I/O gotchas — SpeechRecognition results and errors, speechSynthesis and chrome.tts, mic permission and lifecycle',
    excludes: 'general MV3 service-worker and content-script mechanics — that is chrome-extension; page markup is html',
  },
  marker: 'a browser speech API (SpeechRecognition / speechSynthesis / chrome.tts) referenced in JS/TS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && SPEECH_API.test(text);
    }),
};
